// Quick checks for parse.js. The data-backed part reads the static bundle
// (web/public/data/, generated by `python -m scripts.build_static`) straight from disk.
// Run: node src/parse.test.mjs
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { shortSurnameMatches, parseQuery, bestPerf, matchAthlete, parseTime, extractSlug, deriveName, looksLikeProfile, extractName } from "./parse.js";
import { findAthlete } from "./engine/whatif.js";

const DATA = join(dirname(fileURLToPath(import.meta.url)), "..", "public", "data");
const readJson = (p) => JSON.parse(readFileSync(join(DATA, p), "utf-8"));
let pass = 0, fail = 0;
const eq = (got, want, msg) => {
  const g = JSON.stringify(got), w = JSON.stringify(want);
  if (g === w) { pass++; } else { fail++; console.log(`FAIL ${msg}\n   got  ${g}\n   want ${w}`); };
};

// --- parseTime (multi-digit minutes) ---
eq(parseTime("3:29.50"), 209.5, "parseTime 1500");
eq(parseTime("13:05.00"), 785, "parseTime 5000");
eq(parseTime("27:30.10"), 1650.1, "parseTime 10000");

// --- parseQuery ---
eq(parseQuery("What if Wightman wins a Diamond League final in 3:27.8?", "1500m_men"),
   { athlete: "What if Wightman wins a Diamond League final in 3:27.8?", place: 1, category: "DF", time: "3:27.80" }, "pq wightman");
eq(parseQuery("How does Riva look on the world ranking with a 3:31 win?", "1500m_men"),
   { athlete: "How does Riva look on the world ranking with a 3:31 win?", championship: "world", place: 1, time: "3:31.00" }, "pq world");
eq(parseQuery("women's 5000m: Smith finishes 2nd at the European Champs", "1500m_men"),
   { athlete: "women's 5000m: Smith finishes 2nd at the European Champs", championship: "road_to_birmingham", eventKey: "5000m_women", place: 2, category: "GL" }, "pq event+gender");
eq(parseQuery("steeplechase third place", "1500m_men").eventKey, "3000mSC_men", "pq steeple keeps gender");
eq(parseQuery("Does Nuguse make the Ultimate by winning a Diamond League meeting?", "1500m_men").championship,
   "road_to_ultimate", "pq ultimate");
eq(parseQuery("Does Nuguse make Beijing by winning their national champs?", "1500m_men"),
   { athlete: "Does Nuguse make Beijing by winning their national champs?", championship: "road_to_beijing", place: 1, category: "B" }, "pq beijing");
eq(parseQuery("What if Kerr finishes 2nd at the World Championships?", "1500m_men"),
   { athlete: "What if Kerr finishes 2nd at the World Championships?", championship: "road_to_beijing", place: 2, category: "OW" }, "pq world champs -> beijing");
eq(parseQuery("Does Hull make the team with a 3:56 win?", "1500m_women").championship,
   "road_to_beijing", "pq 'make the team' -> live road to");
eq(parseQuery("What if Hull runs 3:58.00 at a Diamond League meeting?", "1500m_women"),
   { athlete: "What if Hull runs 3:58.00 at a Diamond League meeting?", category: "GW", time: "3:58.00" }, "pq standard example");
eq(parseQuery("What if Chebet wins the World Athletics Ultimate in Budapest?", "5000m_women").championship,
   "road_to_ultimate", "pq ultimate beats 'world'");
eq(parseQuery("Wightman wins nationals in 3:34", "1500m_men").category, "B", "pq nationals -> B (national champs)");
eq(parseQuery("3rd at a national meet", "1500m_men").category, "C", "pq national meet -> C");

// --- extractName (for the unranked NL search) ---
eq(extractName("What if Jake Heyward wins nationals in 3:34"), "Jake Heyward", "name: framed + verb");
eq(extractName("Jake Heyward 3:34 at nationals"), "Jake Heyward", "name: stops at number");
eq(extractName("women's 5000m: Mary Smith finishes 2nd"), "Mary Smith", "name: strips event prefix");
eq(extractName("How does Riva look on the world ranking"), "Riva", "name: stops at 'look'");
eq(parseQuery("the 800 in 1:43.5", "5000m_women").eventKey, "800m_women", "pq 800 keeps women");

// --- extractSlug + deriveName ---
eq(extractSlug("https://worldathletics.org/athletes/great-britain/jake-heyward-14597392"), "jake-heyward-14597392", "slug from url");
eq(extractSlug("https://worldathletics.org/athletes/great-britain/jake-heyward-14597392?foo=1#bar"), "jake-heyward-14597392", "slug strips query/hash");
eq(extractSlug("  jake-heyward-14597392/  "), "jake-heyward-14597392", "slug from bare value + trailing slash");
eq(deriveName("jake-heyward-14597392"), "Jake Heyward", "name from slug");
eq(deriveName("pieter-sisk-14613049"), "Pieter Sisk", "name from slug 2");

// --- looksLikeProfile ---
eq(looksLikeProfile("https://worldathletics.org/athletes/great-britain/jake-heyward-14597392"), true, "profile url");
eq(looksLikeProfile("jake-heyward-14597392"), true, "profile bare slug");
eq(looksLikeProfile("Jake WIGHTMAN"), false, "name not profile");
eq(looksLikeProfile("Narve Gilje NORDÅS"), false, "spaced name not profile");
eq(looksLikeProfile(""), false, "empty not profile");

// --- parseQuery: goal vs venue, ordinals that aren't places, time formats ---
const pq = (q) => { const { athlete, ...r } = parseQuery(q, "1500m_men"); return r; };
eq(pq("Can Josh Kerr qualify for the World Championships with 3:30.00 at a Diamond League?"),
   { championship: "road_to_beijing", category: "GW", time: "3:30.00" }, "worlds as goal, DL as venue");
eq(pq("Kerr wins the World Championships in 3:29.00").category, "OW", "worlds as venue");
eq(pq("what if Kerr runs 3:30.00 at the Olympics").category, "OW", "olympics as venue");
eq(pq("Hovland runs 4:02.50 for third at a national meet to make the final in Beijing"),
   { championship: "road_to_beijing", place: 3, category: "C", time: "4:02.50" }, "'make the final' is a goal");
eq(pq("Kerr 3:31.00 to make the final").category, undefined, "'make the final' alone sets no category");
eq(pq("Kerr wins the Diamond League final in 3:29.00").category, "DF", "DL final as venue");
eq(pq("Kerr runs 3:29.5 in his first race of the season, finishing 4th").place, 4, "explicit place beats 'first race'");
eq(pq("Kerr runs 3:29.5 in his first race of the season").place, undefined, "'first race' is not a place");
eq(pq("Hodgkinson 1:54.6 on 23rd May in Rabat").place, undefined, "date ordinal is not a place");
eq(pq("Hodgkinson 1:54.6 on May 23rd in Rabat").place, undefined, "month-first date is not a place");
eq(pq("Kerr comes second in 3:30.00").place, 2, "second");
eq(pq("Kerr 5th in 3:30.00").place, 5, "bare ordinal");
eq(pq("Kerr wins his 2nd Diamond League in 3:30.00").place, 1, "win beats a counting ordinal");
eq(pq("Wanyonyi 1.41.50 Diamond League final win").time, "1:41.50", "dotted time");
eq(pq("Kerr 3:29,50 in Monaco").time, "3:29.50", "comma decimal");
eq(pq("Kerr 3:29.50 on 12.06.27").time, "3:29.50", "a dotted date after a real time is ignored");

// --- real data (static bundle): bestPerf + matchAthlete ---
const main = async () => {
  const rk = readJson("rankings/road_to_beijing__1500m_men.json");
  const list = rk.athletes;
  eq(matchAthlete("what if WIGHTMAN wins", list), "Jake WIGHTMAN", "match surname");
  eq(matchAthlete("how about nader", list), "Isaac NADER", "match lowercase surname");
  eq(matchAthlete("nobody here", list), null, "match miss");

  // Whole words only: short surnames must not match inside ordinary words ("HE" in "the"),
  // and extra name words pick the right athlete among shared surnames / middle names.
  const fake = [{ name: "Wuga HE" }, { name: "Kelvin KIPLAGAT" }, { name: "Emmanuel Korir KIPLAGAT" },
                { name: "Aaron AHL" }, { name: "Zakaria EL AHLAAMI" }, { name: "Diane VAN ES" },
                { name: "Elvin Josué CANALES" }, { name: "Josue LE CADRE" }];
  eq(matchAthlete("what if she wins the final and makes the team", fake), null, "no ghost match on 'the'");
  eq(matchAthlete("what if he wins", fake), null, "short surname alone is not a match");
  eq(matchAthlete("Wuga He runs 31:00.00", fake), "Wuga HE", "short surname with given name");
  eq(matchAthlete("Emmanuel Kiplagat wins", fake), "Emmanuel Korir KIPLAGAT", "middle name skipped");
  eq(matchAthlete("kiplagat wins", fake), "Kelvin KIPLAGAT", "shared surname -> higher ranked");
  eq(matchAthlete("Zakaria Ahlaami 8:10.00", fake), "Zakaria EL AHLAAMI", "no substring surname hit");
  eq(matchAthlete("diane van es in 14:50.00", fake), "Diane VAN ES", "multi-word surname");
  eq(matchAthlete("Josue Cadre 1:44.00", fake), "Josue LE CADRE", "most name words wins");

  eq(shortSurnameMatches("He", fake), ["Wuga HE"], "short surname alone -> hint");
  eq(shortSurnameMatches("Kiplagat", fake), [], "long surname -> no hint");
  eq(shortSurnameMatches("Wuga He", fake), [], "with a given name -> no hint");

  // Every athlete on every live list resolves to themselves from "First Last".
  const meta = readJson("meta.json");
  for (const e of meta.events) {
    const l = readJson(`rankings/road_to_beijing__${e.key}.json`).athletes;
    const wrong = l.filter((a) => {
      const t = a.name.split(" ");
      return matchAthlete(`what if ${t[0]} ${t[t.length - 1].toLowerCase()} wins the final`, l) !== a.name;
    }).map((a) => a.name);
    eq(wrong, [], `first+last resolves on ${e.key}`);
    eq(matchAthlete("what if someone wins the diamond league final and makes the team", l), null, `no ghost on ${e.key}`);

    // bestPerf: only ever a Main Event mark (10000m is "10K", steeple "3KSC").
    const full = readJson(`lists/world__${e.key}.json`).athletes;
    const bad = full.filter((a) => {
      const b = bestPerf(a, e.main_event_codes);
      const mains = a.performances.filter((p) => e.main_event_codes.includes(p.discipline_code));
      return mains.length ? !(b && mains.some((p) => p.mark === b.time)) : b !== null;
    }).map((a) => a.name);
    eq(bad, [], `bestPerf seeds a main-event mark on ${e.key}`);
  }

  const ath = findAthlete(readJson("lists/world__1500m_men.json"), "Jake WIGHTMAN");
  const best = bestPerf(ath, ["1500"]);
  // Data refreshes weekly, so assert the *rule*, not a mark: bestPerf must return the
  // main-event (code 1500) performance with the highest result score.
  const mains = ath.performances.filter((p) => p.discipline_code === "1500");
  const top = mains.reduce((a, b) => (b.result_score > a.result_score ? b : a));
  eq(best, { time: top.mark, place: String(top.place), category: top.category }, "bestPerf main-event fastest");

  console.log(`\n${pass} passed, ${fail} failed`);
  process.exit(fail ? 1 : 0);
};
main().catch((e) => { console.error("test error:", e.message); process.exit(2); });
